import{z as B,x as p,o as E,c as d,q as l,j as s,D as e,d as i,s as n,S as A,b as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"堆文件与聚簇","description":"","frontmatter":{"title":"堆文件与聚簇","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/heap-cluster.md","filePath":"cs/heap-cluster.md","lastUpdated":1791413859000}'),o={name:"cs/heap-cluster.md"};function h(m,a,c,u,C,D){const t=p("Mermaid");return E(),d("div",null,[a[2]||(a[2]=l('<h1 id="堆文件与聚簇" tabindex="-1">堆文件与聚簇 <a class="header-anchor" href="#堆文件与聚簇" aria-label="Permalink to &quot;堆文件与聚簇&quot;">​</a></h1><div class="epigraph"><p>堆按插入摆放；聚簇按键把相邻元组放进相邻页，范围扫描才不必满世界跳。</p><footer>—— 据 Ramakrishnan and Gehrke；Gray and Reuter 对文件组织的整理</footer></div><p><a href="/cs/page-slot">上一课</a>给出槽化页与 rid。本课不重画页头。缺口是：一堆页如何组成一张表的存储。堆文件几乎只保证「能插入、能扫全表」；聚簇把同一键区间的行放在物理上相近的页里，让范围查询的 I/O 变顺序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全表扫描走堆：顺着页链表或空间图读。点查若只靠堆，只能扫。索引可以拿 rid 回表，但若目标行在磁盘上随机散布，二次 I/O 仍碎。<a href="/cs/btree-external">B 树</a>已经能按键找；本课问的是<strong>数据页本身怎么排</strong>。聚簇索引（或聚簇堆）让叶上的顺序与页上的顺序一致；堆加二级索引则行序与键序无关。</p><p><span class="marginnote">聚簇是文件组织，不是「多建一棵树」的同义词。一张表通常只有一种聚簇序；其余索引都是非聚簇，必须 rid 回表。</span></p><p><span class="marginnote">直觉类比：堆文件像往抽屉里随手塞信，谁先到放谁旁边；聚簇像图书馆按索书号上架——「内容挨着的书」在书架上也真挨着。找「QA100 到 QA200」这一段，前者满库乱跑，后者顺架走一遍。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>堆：空闲空间图找到够放的页，插入占用一个槽，rid 新分配。删除留洞，可填可整理。聚簇：按主键（或指定键）排序装页，插入若页满则分裂或溢页，以保持键的大致邻近。本课不把索引内部结构写完，只区分「数据即叶」与「数据在堆、索引只存键和 rid」。</p>',9)),(E(),s(A,null,{default:e(()=>[n(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20RID%5B%22rid%22%5D%20--%3E%20HEAP%5B%22%E5%A0%86%3A%20%E6%8F%92%E5%85%A5%E5%BA%8F%22%5D%0A%20%20RID%20--%3E%20CLUS%5B%22%E8%81%9A%E7%B0%87%3A%20%E9%94%AE%E5%BA%8F%E9%82%BB%E8%BF%91%22%5D%0A%20%20HEAP%20--%3E%20IDX%5B%22%E5%90%8E%E8%AF%BE%3A%20B%2B%20%E7%B4%A2%E5%BC%95%22%5D%0A%20%20CLUS%20--%3E%20IDX%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[i("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"范围查询在聚簇文件上接近顺序预读；在堆上即使有二级索引，也会变成随机 rid 追记录——这正是前几课代价模型里「回表随机 I/O」那一项。插入在堆上便宜，在聚簇上可能触发页分裂，改变已有 rid 或依赖转发。批量装载按键排序一次写成聚簇，比逐条插入少分裂。",-1)),a[5]||(a[5]=r("p",null,"同一条范围查询，两种文件组织的 I/O 账：",-1)),(E(),s(A,null,{default:e(()=>[n(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%8C%83%E5%9B%B4%E6%9F%A5%E8%AF%A2%3A%20%E9%94%AE%E5%9C%A8%20100..200%22%5D%20--%3E%20C%5B%22%E8%81%9A%E7%B0%87%3A%20%E5%8F%B6%E5%BA%8F%3D%E9%A1%B5%E5%BA%8F%22%5D%0A%20%20C%20--%3E%20C1%5B%22%E7%9B%B8%E9%82%BB%E9%94%AE%E8%90%BD%E5%9C%A8%E7%9B%B8%E9%82%BB%E9%A1%B5%22%5D%0A%20%20C1%20--%3E%20C2%5B%22%E9%A1%BA%E5%BA%8F%E9%A2%84%E8%AF%BB%2C%20I%2FO%E2%89%88%E9%A1%B5%E6%95%B0%22%5D%0A%20%20Q%20--%3E%20H%5B%22%E5%A0%86%2B%E4%BA%8C%E7%BA%A7%E7%B4%A2%E5%BC%95%22%5D%0A%20%20H%20--%3E%20H1%5B%22%E7%B4%A2%E5%BC%95%E5%90%90%E5%87%BA%E4%B8%80%E4%B8%B2%20rid%22%5D%0A%20%20H1%20--%3E%20H2%5B%22%E8%A1%8C%E9%9A%8F%E6%9C%BA%E6%95%A3%E5%B8%83%2C%20%E9%80%90%20rid%20%E5%9B%9E%E8%A1%A8%22%5D%0A%20%20H2%20--%3E%20H3%5B%22%E6%AF%8F%E8%A1%8C%E5%8F%AF%E8%83%BD%E4%B8%80%E6%AC%A1%E9%9A%8F%E6%9C%BA%20I%2FO%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">数字实例：命中 1 万行的范围查询，聚簇下若每页 100 行、页间连续，约 100 次顺序页读；堆+二级索引则 1 万个 rid 各自回表，按每次随机 I/O 5 毫秒算是 50 秒对约 0.1 秒——三个数量级的差距就是这么算出来的。</span></p><p>多表聚簇（把一对多的行交叉存放）能加速特定连接，但破坏单表扫描的简单图像，主干只点名，不做成默认。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲分区表、列存、HTAP 的双格式。也不把「主键一定聚簇」写成公理：有的引擎堆+二级主键索引。后课 B+ 树默认可以挂在堆上当二级索引，也可以自己当聚簇叶。</p><p>TID 扫描（先从索引收集 rid 再按页排序回表）是堆组织上的代价修补，本课只点名：随机 rid 可以排成页序，仍不是聚簇。后课默认：表有一种主文件组织（堆或聚簇）；索引是附加的访问路径。</p><p><span class="marginnote">常见误区：初学者容易把「建了索引」当成「查询一定快」。在堆组织上，非聚簇索引拿到 rid 还要回去取整行；选择率一大，回表随机 I/O 反而比直接扫全表更贵——优化器这时会宁扫堆也不用索引。</span></p><p>文件组织一旦选定，查询计划的访问路径才有「扫堆还是走叶序」这一问。本课不改逻辑模式，只改物理邻近。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>批量按键装载比逐条插入少分裂，这是装载路径，不是另一种查询语言。</p></li><li><p>后课 B+ 可以当聚簇叶，也可以当堆上的二级索引。</p></li><li><p>页与槽已在；本课在文件级选择堆或按键聚簇。</p></li><li><p>聚簇加速范围与有序扫描，插入与分裂更贵。</p></li><li><p>B+ 树如何当索引头，是后课缺口。</p></li><li><p>出处：Ramakrishnan and Gehrke；Garcia-Molina, Ullman and Widom。</p></li></ul>',9))])}const F=B(o,[["render",h]]);export{_ as __pageData,F as default};
